From 44f3a85f24e2fb119396ea7020f9ddff67cc6506 Mon Sep 17 00:00:00 2001
From: Pat Gaffney <pat@hypepat.com>
Date: Tue, 27 Dec 2016 23:19:17 -0600
Subject: [PATCH] Fix leading WS on opening code fences

This fixes an error that was introduced in 913c28d.

diff --git a/parsers.c b/parsers.c
index ac4cd0a..d73b264 100644
--- a/parsers.c
+++ b/parsers.c
@@ -564,14 +564,12 @@ static ssize_t is_closing_code_fence(uint8_t *data, CodeBlk *blk)
  */
 static size_t parse_fenced_code_block(uint8_t *data, CodeBlk *blk, size_t i)
 {
-    String *cb = init_string(BLK_BUF);
-    size_t ws  = 0;
+    String *cb  = init_string(BLK_BUF);
     ssize_t cfl = 0;    /* Closing-fence line length (in bytes). */

     /* Parse every line as part of this code block 
      * until we find the closing fence. */
     while (true) {
-        ws = count_indentation(data);

         /* Check this line for a code fence. */
         if ((cfl = is_closing_code_fence(data, blk)) > 0) break;
@@ -579,7 +577,7 @@ static size_t parse_fenced_code_block(uint8_t *data, CodeBlk *blk, size_t i)

         /* Advance past the WS on the opening code fence. */
         size_t linews = 0;
-        while (blk->ws > 0 && ws > 0 && linews < blk->ws) {
+        while (blk->ws > 0 && *data == 0x20 && linews < blk->ws) {
             data++, i++;
             linews++;
         }
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by an incorrect handling of leading whitespace on opening code fences, where the logic relied on a variable (`ws`) that was not necessary. This led to potential misinterpretation of the actual whitespace characters, resulting in errors when parsing fenced code blocks. The fix involved directly checking for space characters instead of using the variable, which corrected the parsing behavior.

        Commit message:
        Fix leading WS on opening code fences

This fixes an error that was introduced in 913c28d.  

        Patch:
          */
 static size_t parse_fenced_code_block(uint8_t *data, CodeBlk *blk, size_t i)
 {
-    String *cb = init_string(BLK_BUF);
-    size_t ws  = 0;
+    String *cb  = init_string(BLK_BUF);
     ssize_t cfl = 0;    /* Closing-fence line length (in bytes). */

     /* Parse every line as part of this code block 
      * until we find the closing fence. */
     while (true) {
-        ws = count_indentation(data);

         /* Check this line for a code fence. */
         if ((cfl = is_closing_code_fence(data, blk)) > 0) break;
         else cfl = 0;

         /* Advance past the WS on the opening code fence. */
         size_t linews = 0;
-        while (blk->ws > 0 && ws > 0 && linews < blk->ws) {
+        while (blk->ws > 0 && *data == 0x20 && linews < blk->ws) {
             data++, i++;
             linews++;
         }

         /* Add characters until we reach a newline. */
         while (*data && *data != '\n') {
             if (cb->length < cb->allocd - NEWLINE - NULL_CHAR) {
                 *cb->data++ = *data++;
                 cb->length++;
                 i++;
             }
             else realloc_string(cb, cb->allocd + BLK_BUF);
         }

         /* Add the newline. */
         *cb->data++ = '\n';
         cb->length++;

         if (!(*data)) break;
         i++, data++;
     }

     *cb->data = '\0';
     cb->data -= cb->length;
     add_markdown(cb, FENCED_CODE_BLOCK, blk);
     return i + cfl;
 }



